```js
export function brickHit(ball, bricks) {
  const px = Number.isFinite(ball.prevX) ? ball.prevX : ball.x;
  const py = Number.isFinite(ball.prevY) ? ball.prevY : ball.y;
  const sx = ball.x - px;
  const sy = ball.y - py;
  const dist = Math.hypot(sx, sy);
  const steps = Math.max(1, Math.ceil(dist / 8));

  const destroyed = [];
  // Which bricks are hit along the entire path? Collect them.
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const bx = px + sx * t;
    const by = py + sy * t;
    for (const brick of bricks) {
      if (!brick.alive) continue;
      if (pointInBrick(bx, by, ball.r, brick)) {
        brick.alive = false;
        destroyed.push(brick);
      }
    }
  }

  if (destroyed.length > 0) {
    // resolve ONE bounce against the first hit brick, so a double neighbor flip
    // (vy=-vy then vy=-vy) cannot cancel itself out.
    resolveBounce(ball, destroyed[0], px, py);
  }
  return destroyed;
}
```

