```js
function resolveBounce(ball, brick, bx, by) {
  // penetration along each axis at the hit sample
  const overlapXLeft = bx + ball.r - brick.x;
  const overlapXRight = brick.x + brick.w - (bx - ball.r);
  const overlapYTop = by + ball.r - brick.y;
  const overlapYBottom = brick.y + brick.h - (by - ball.r);
  const penX = Math.min(overlapXLeft, overlapXRight);
  const penY = Math.min(overlapYTop, overlapYBottom);

  if (penX < penY) {
    // side hit
    ball.vx = -ball.vx;
    if (overlapXLeft < overlapXRight) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
  } else if (penY < penX) {
    ball.vy = -ball.vy;
    if (overlapYTop < overlapYBottom) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
  } else {
    // corner: flip both
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    // push out both axes
    ball.x = overlapXLeft < overlapXRight ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = overlapYTop < overlapYBottom ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}
```

